CREATE TABLE cxx_turn_index ( -- 回合索引表
  row_id INTEGER PRIMARY KEY, -- 行号
  turn_no INTEGER NOT NULL UNIQUE CHECK(turn_no >= 0), -- 回合
  summary TEXT CHECK(summary IS NULL OR LENGTH(summary) <= 300), -- 摘要
  entities TEXT CHECK(entities IS NULL OR LENGTH(entities) <= 200) -- 涉及实体
);
